package org.vellum.panel.enroll

import kotlinx.serialization.encodeToString
import org.vellum.panel.data.PanelJson
import java.io.File
import java.io.FileOutputStream
import java.nio.file.Files
import java.nio.file.StandardCopyOption
import javax.crypto.Cipher
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

interface IdentityStore {
    fun load(): DeviceIdentity?

    fun save(identity: DeviceIdentity)

    fun clear()
}

/** Random IVs are generated by the cipher provider, including Android Keystore. */
class SecretBox(
    private val key: SecretKey,
) {
    fun seal(plaintext: ByteArray): ByteArray {
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        cipher.init(Cipher.ENCRYPT_MODE, key)
        return cipher.iv + cipher.doFinal(plaintext)
    }

    fun open(ciphertext: ByteArray): ByteArray {
        require(ciphertext.size > 28)
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        cipher.init(Cipher.DECRYPT_MODE, key, GCMParameterSpec(128, ciphertext.copyOfRange(0, 12)))
        return cipher.doFinal(ciphertext.copyOfRange(12, ciphertext.size))
    }
}

class EncryptedIdentityStore(
    private val file: File,
    private val box: SecretBox,
) : IdentityStore {
    override fun load(): DeviceIdentity? {
        if (!file.exists()) return null
        val plaintext = box.open(file.readBytes())
        return try {
            PanelJson.decodeFromString<DeviceIdentity>(plaintext.toString(Charsets.UTF_8))
        } finally {
            plaintext.fill(0)
        }
    }

    override fun save(identity: DeviceIdentity) {
        val plaintext = PanelJson.encodeToString(identity).toByteArray(Charsets.UTF_8)
        try {
            atomicWrite(file, box.seal(plaintext))
        } finally {
            plaintext.fill(0)
        }
    }

    override fun clear() {
        if (!file.delete() &&
            file.exists()
        ) {
            throw java.io.IOException("Unable to remove device identity")
        }
    }
}

fun atomicWrite(
    file: File,
    bytes: ByteArray,
) {
    file.parentFile!!.mkdirs()
    val temp = File.createTempFile(".panel-", ".tmp", file.parentFile)
    try {
        FileOutputStream(temp).use {
            it.write(bytes)
            it.fd.sync()
        }
        Files.move(
            temp.toPath(),
            file.toPath(),
            StandardCopyOption.ATOMIC_MOVE,
            StandardCopyOption.REPLACE_EXISTING,
        )
    } finally {
        temp.delete()
    }
}
